/** Reopen a closed period, by a steward only: its fixed due-total is dropped, so it totals the
 *  claims in it live again (bound ones at their bound figure). */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            ServerHttpConnection connection, PeriodRepository repository, SettingsRepository settings, Audit audit,
            Out<Period> period) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.lockSheet(id)) {
            throw new BadRequestException("no such sheet");
        }
        Period found = repository.find(id, periodName == null ? "" : periodName.trim());
        if (found == null) {
            throw new BadRequestException("no such period");
        }
        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
            throw new BadRequestException("only a steward can reopen a period");
        }
        if (!found.closed()) {
            throw new BadRequestException("the period " + found.name() + " is not closed");
        }
        repository.reopen(id, found.id());
        audit.record("PERIOD_REOPENED sheet=" + id + " by=" + by + " period=" + found.name());
        period.set(new Period(found.id(), found.name(), found.from(), found.to(), false, null, java.util.Map.of()));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Hold;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Close a period: fix its due-total as shown now (the dues now, late charges included, of the claims dated in it that count by
 *  the status they had at the end of its last day, a person's
 *  open (OPEN or PENDING) claims dated within one of their holds left out unless bound by a statement,
 *  skipping those with none), so later changes to rates do not alter it; and each person's due-total for it
 *  likewise, for every person on the sheet (0.00 for one with nothing in it). */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            ServerHttpConnection connection, PeriodRepository repository, ClaimRepository claims, PersonRepository people, Audit audit,
            Out<Period> period) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.lockSheet(id)) {
            throw new BadRequestException("no such sheet");
        }
        Period found = repository.find(id, periodName == null ? "" : periodName.trim());
        if (found == null) {
            throw new BadRequestException("no such period");
        }
        if (found.closed()) {
            throw new BadRequestException("the period " + found.name() + " is already closed");
        }
        LocalDate from = LocalDate.parse(found.from());
        LocalDate to = LocalDate.parse(found.to());
        Map<Long, List<Hold>> holds = people.holds(id);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        for (Person p : people.list(id)) personTotals.put(p.id(), BigDecimal.ZERO.setScale(2));
        Map<Long, String> statusesThen = claims.statusesOn(id, to);
        String today = repository.today(id);
        for (Claim c : claims.list(id)) {
            LocalDate on = LocalDate.parse(c.date());
            if (on.isBefore(from) || on.isAfter(to)
                    || !c.countsAs(statusesThen.get(c.id()), holds.getOrDefault(c.personId(), List.of()), today)) continue;
            BigDecimal now = claims.dueNow(id, c);
            if (now != null) {
                total = total.add(now);
                personTotals.merge(c.personId(), now, BigDecimal::add);
            }
        }
        String shown = total.setScale(2).toPlainString();
        repository.close(id, found.id(), total, personTotals);
        audit.record("PERIOD_CLOSED sheet=" + id + " by=" + by + " period=" + found.name() + " total=" + shown);
        period.set(new Period(found.id(), found.name(), found.from(), found.to(), true, shown, personTotals.entrySet().stream().collect(Collectors.toMap(e -> Long.toString(e.getKey()),
                e -> e.getValue().setScale(2).toPlainString(), (a, b) -> a, LinkedHashMap::new))));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Move a DRAFT, OPEN or PENDING claim to another person on the sheet; only a steward may. The claim keeps its
 *  number and date, loses any figure a statement bound it to (live again until its new person's next
 *  statement) and is listed as its new person's newest claim. Every check is made before anything is written. */
public class ReassignClaim {
    public void reassign(@PathVariable("sheetId") String sheetId, @RequestBody ReassignRequest request,
            ServerHttpConnection connection, ClaimRepository repository, PeriodRepository periods,
            SettingsRepository settings, Audit audit, Rollup rollup, Out<Claim> claim) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (request == null || request.claimId() == null) {
            throw new BadRequestException("no such claim");
        }
        if (request.personId() == null) {
            throw new BadRequestException("choose the person to move the claim to");
        }
        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
            throw new BadRequestException("only a steward can reassign a claim");
        }
        Claim found = repository.find(id, request.claimId());
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        if (!found.status().equals("DRAFT") && !found.open()) {
            throw new BadRequestException("a " + found.status() + " claim cannot be reassigned");
        }
        long to = request.personId();
        if (!repository.personExists(id, to)) {
            throw new BadRequestException("no such person");
        }
        if (to == found.personId()) {
            throw new BadRequestException("the claim is already that person's");
        }
        PeriodGuard.open(periods, id, LocalDate.parse(found.date()));
        String fromName = repository.personName(id, found.personId());
        String toName = repository.personName(id, to);
        Rollup.Snapshot before = rollup.take(id);
        if (!repository.reassign(id, found.id(), to)) {
            throw new BadRequestException("a " + found.status() + " claim cannot be reassigned");
        }
        Claim moved = new Claim(found.id(), to, found.amount(), found.date(), found.note(), found.status(),
                found.number(), found.due(), found.openedBy(), false, null, found.corrects(), found.dueBy(), false,
                found.deferredUntil(), found.deferred(), found.proofs());
        audit.record("CLAIM_REASSIGNED sheet=" + id + " by=" + by + " person=" + toName + " amount=" + moved.amount()
                + " date=" + moved.date() + Claim.auditNumber(moved.number()) + " from=" + fromName + " to=" + toName);
        rollup.record(id, by, before);
        claim.set(moved);
    }
}
